import logging
import queue
import time
from abc import ABC
from pprint import pformat
from string import Template
from typing import Callable, Dict

import pexpect  # type: ignore
from ta_tshark_json_parser.tshark_source import TsharkSource  # type: ignore
from ute_common_abstract_core.message import Message  # type: ignore

from taf.ul.sbts.pmi_ticket_collector.logger_config import (  # type: ignore[import-untyped]
    configure_msg_source_logger,
)

CPUE_TSHARK_COMMAND = "tshark -i any -Y 'protobuf' -T json -f 'tcp src port 30512' -l"

CPRT_TSHARK_COMMAND = Template(
    "sshpass -p $password ssh $user@$ip -p 22 "
    '"tcpdump -i any src port 15066 -s 0 -U -n -w -" |'
    " tshark -i -  -Y 'protobuf' -T json -l"
)

configure_msg_source_logger("tshark_source_raw")
configure_msg_source_logger("_pmi_ticket_raw")

logger = logging.getLogger("pmi_ticket_collector.tshark_source")
pmi_ticket_logger = logging.getLogger("_pmi_ticket_raw")
tshark_source_raw_logger = logging.getLogger("tshark_source_raw")


class PMITsharkSource(TsharkSource, ABC):
    def __init__(self, protocol: str, callback: Callable):
        self._protocol: str = protocol
        self._callback: Callable = callback
        self._queue: queue.Queue = queue.Queue()
        super().__init__(queue=self._queue, layer=self._protocol, duplicated_keys_handler="as_list")
        logger.debug("Tshark started.")

    def process_data_record(self, data_record: dict) -> dict:
        """to be added"""
        tshark_source_raw_logger.info("\n" + pformat(data_record) + "\n")
        if self._callback is not None:
            protocols = data_record["_source"]["layers"]
            for protocol_name in (proto for proto in protocols.keys() if self._protocol in proto):
                pmi_ticket_logger.debug("\n" + pformat(protocols[protocol_name]) + "\n")
                self._handle_msg(protocols, protocol_name)
        return data_record

    def _handle_msg(self, record: dict, protocol_name: str):
        raise NotImplementedError

    def get_unique_logger_name(self):
        return f"{type(self).__name__}"

    def get_opened_connection(self) -> pexpect.spawn:
        """to be added"""
        return self.get_opened_connection_local()

    def get_opened_connection_local(self):
        """
        Returns established connection object to data stream (inheritance API)

        :return: connection
        """
        self.logger.info("Starting tshark connection locally using pexpect spawn")
        process = pexpect.spawn("/bin/bash", ["-c", self._get_tshark_command()])
        process.expect("Capturing on")
        time.sleep(1)
        return process


class CpRtPMITsharkSource(PMITsharkSource):
    def __init__(self, cprt_data: Dict[str, str], callback: Callable):
        self._cprt_data = cprt_data
        super().__init__("CpRtPmiTicket", callback)

    def _handle_msg(self, protocols: dict, protocol_name: str):
        record = protocols[protocol_name]
        self._callback(Message(record, {"gnb_id": self._cprt_data["gnb_id"]}))

    def get_tshark_command(self) -> str:
        """to be added"""
        return CPRT_TSHARK_COMMAND.substitute(
            password=self._cprt_data["password"], user=self._cprt_data["user"], ip=self._cprt_data["cu_ip"]
        )


class CpUePMITsharkSource(PMITsharkSource):
    def __init__(self, callback: Callable):
        super().__init__("CpUePmiTicket", callback)
        logger.debug("Tshark started.")

    def get_tshark_command(self) -> str:
        """to be added"""
        return CPUE_TSHARK_COMMAND

    def _handle_msg(self, protocols: dict, protocol_name: str):
        record = protocols[protocol_name]
        self._callback(Message(record, {"src_ip": protocols["ip"]["ip.src"]}))
